pub fn placeholder_type_node(name: String) -> Rc<Node> {
    nominal_type_ref(name)
}

pub fn nominal_type_ref(name: String) -> Rc<Node> {
    leaf_node_with_span(name.clone(), kernel_span(name.clone()))
}

pub fn algebra_child_or_placeholder(
    base: Rc<Node>,
    child_index: i64,
    placeholder: String,
) -> Rc<Node> {
    match Rc::new({
        let mut __result = Vec::new();
        for pair in Rc::new({
            let mut __result = Vec::new();
            for pair in Rc::new(
                base.children
                    .clone()
                    .iter()
                    .cloned()
                    .enumerate()
                    .map(|(i, v)| (i as i64, v))
                    .collect::<Vec<_>>(),
            )
            .iter()
            .cloned()
            {
                if (pair.0.clone() == child_index.clone()) {
                    __result.push(pair);
                }
            }
            __result
        })
        .iter()
        .cloned()
        {
            __result.push(pair.1.clone());
        }
        __result
    })
    .first()
    .cloned()
    {
        Some(child) => child_type_node(child.clone()),
        None => type_variable_node(placeholder),
    }
}

pub fn instantiate_algebra_type(
    template: Rc<AlgebraTypeTemplate>,
    base: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<KernelTypeBuild> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let elem = algebra_child_or_placeholder(base.clone(), 0, "T".to_string());
        let key_node = algebra_child_or_placeholder(base.clone(), 0, "K".to_string());
        let val_node = algebra_child_or_placeholder(base.clone(), 1, "V".to_string());
        match (*template).clone() {
            AlgebraTypeTemplate::ReceiverSelf => Rc::new(KernelTypeBuild {
                ty: base.clone(),
                diagnostics: Rc::new(vec![]),
            }),
            AlgebraTypeTemplate::ReceiverElement => Rc::new(KernelTypeBuild {
                ty: elem,
                diagnostics: Rc::new(vec![]),
            }),
            AlgebraTypeTemplate::ReceiverKey => Rc::new(KernelTypeBuild {
                ty: key_node,
                diagnostics: Rc::new(vec![]),
            }),
            AlgebraTypeTemplate::ReceiverValue => Rc::new(KernelTypeBuild {
                ty: val_node,
                diagnostics: Rc::new(vec![]),
            }),
            AlgebraTypeTemplate::NamedTemplate { name: n, .. } => Rc::new(KernelTypeBuild {
                ty: nominal_type_ref(n.clone()),
                diagnostics: Rc::new(vec![]),
            }),
            AlgebraTypeTemplate::AlgebraTypeVariable { id: var_id, .. } => {
                Rc::new(KernelTypeBuild {
                    ty: type_variable_node(var_id.clone()),
                    diagnostics: Rc::new(vec![]),
                })
            }
            AlgebraTypeTemplate::ContainerOf {
                source: src,
                element: inner,
                ..
            } => {
                let kind_name = match (*src.clone()).clone() {
                    ContainerSource::SameAsReceiver => {
                        authored_name_at(source_indices.clone(), base.clone())
                    }
                    ContainerSource::Named { name: n, .. } => n.clone(),
                };
                let inner_b =
                    instantiate_algebra_type(inner.clone(), base.clone(), source_indices.clone());
                let built = make_container_type(kind_name, inner_b.ty.clone());
                Rc::new(KernelTypeBuild {
                    ty: built.ty.clone(),
                    diagnostics: v1_rt::concat(
                        inner_b.diagnostics.clone(),
                        built.diagnostics.clone(),
                    ),
                })
            }
            AlgebraTypeTemplate::OptionalOf { inner: inner, .. } => {
                let ib =
                    instantiate_algebra_type(inner.clone(), base.clone(), source_indices.clone());
                Rc::new(KernelTypeBuild {
                    ty: with_optional_cardinality(ib.ty.clone()),
                    diagnostics: ib.diagnostics.clone(),
                })
            }
            AlgebraTypeTemplate::WitnessOf { inner: inner, .. } => {
                let ib =
                    instantiate_algebra_type(inner.clone(), base.clone(), source_indices.clone());
                let built = make_container_type("Witness".to_string(), ib.ty.clone());
                Rc::new(KernelTypeBuild {
                    ty: built.ty.clone(),
                    diagnostics: v1_rt::concat(ib.diagnostics.clone(), built.diagnostics.clone()),
                })
            }
            AlgebraTypeTemplate::TupleOf { first, second, .. } => {
                let fb =
                    instantiate_algebra_type(first.clone(), base.clone(), source_indices.clone());
                let sb =
                    instantiate_algebra_type(second.clone(), base.clone(), source_indices.clone());
                Rc::new(KernelTypeBuild {
                    ty: make_tuple_type(fb.ty.clone(), sb.ty.clone()),
                    diagnostics: v1_rt::concat(fb.diagnostics.clone(), sb.diagnostics.clone()),
                })
            }
            AlgebraTypeTemplate::CallableOf {
                params: p,
                return_type: r,
                ..
            } => {
                let param_bs = Rc::new({
                    let mut __result = Vec::new();
                    for tp in p.clone().iter().cloned() {
                        __result.push(instantiate_algebra_type(
                            tp.clone(),
                            base.clone(),
                            source_indices.clone(),
                        ));
                    }
                    __result
                });
                let param_diags = Rc::new({
                    let mut __result = Vec::new();
                    for b in param_bs.clone().iter().cloned() {
                        __result.extend((*b.diagnostics.clone()).iter().cloned());
                    }
                    __result
                });
                let param_nodes = Rc::new({
                    let mut __result = Vec::new();
                    for b in param_bs.clone().iter().cloned() {
                        __result.push(b.ty.clone());
                    }
                    __result
                });
                let rb = instantiate_algebra_type(r.clone(), base.clone(), source_indices.clone());
                Rc::new(KernelTypeBuild {
                    ty: make_callable_type(param_nodes, rb.ty.clone()),
                    diagnostics: v1_rt::concat(param_diags, rb.diagnostics.clone()),
                })
            }
        }
    })
}

pub fn instantiate_algebra_field(
    template: Rc<AlgebraFieldTemplate>,
    base: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<KernelTypeBuild> {
    {
        let param_bs = Rc::new({
            let mut __result = Vec::new();
            for tp in template.param_types.clone().iter().cloned() {
                __result.push(instantiate_algebra_type(
                    tp.clone(),
                    base.clone(),
                    source_indices.clone(),
                ));
            }
            __result
        });
        let param_types = Rc::new({
            let mut __result = Vec::new();
            for b in param_bs.clone().iter().cloned() {
                __result.push(b.ty.clone());
            }
            __result
        });
        let param_diags = Rc::new({
            let mut __result = Vec::new();
            for b in param_bs.clone().iter().cloned() {
                __result.extend((*b.diagnostics.clone()).iter().cloned());
            }
            __result
        });
        let return_b = instantiate_algebra_type(
            template.return_type.clone(),
            base.clone(),
            source_indices.clone(),
        );
        let field_ty = if ((param_types.clone().len() as i64) > 0) {
            algebra_method_field(
                template.name.clone(),
                param_types.clone(),
                return_b.ty.clone(),
            )
        } else {
            algebra_value_field(template.name.clone(), return_b.ty.clone())
        };
        Rc::new(KernelTypeBuild {
            ty: field_ty,
            diagnostics: v1_rt::concat(param_diags, return_b.diagnostics.clone()),
        })
    }
}

pub fn enrich_kernel_type(
    name: String,
    base: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<KernelTypeBuild> {
    {
        if std::env::var_os("GUNBC_DEBUG_ENRICH").is_some() { eprintln!("[enrich_kernel_type] name={:?} connective={:?} children={}", name, base.connective, base.children.len()); }
        let profile = v1_rt::map_get(&kernel_algebra_profile(), name.clone());
        match profile {
            Some(p) => {
                let field_bs = Rc::new({
                    let mut __result = Vec::new();
                    for template in algebra_templates_for_profile(p.clone()).iter().cloned() {
                        __result.push(instantiate_algebra_field(
                            template.clone(),
                            base.clone(),
                            source_indices.clone(),
                        ));
                    }
                    __result
                });
                let fields = Rc::new({
                    let mut __result = Vec::new();
                    for b in field_bs.clone().iter().cloned() {
                        __result.push(b.ty.clone());
                    }
                    __result
                });
                let field_diags = Rc::new({
                    let mut __result = Vec::new();
                    for b in field_bs.clone().iter().cloned() {
                        __result.extend((*b.diagnostics.clone()).iter().cloned());
                    }
                    __result
                });
                Rc::new(KernelTypeBuild {
                    ty: enrich_base_with_fields(name.clone(), base.clone(), fields),
                    diagnostics: field_diags,
                })
            }
            None => Rc::new(KernelTypeBuild {
                ty: base.clone(),
                diagnostics: Rc::new(vec![]),
            }),
        }
    }
}

pub fn unify_template(
    template: Rc<AlgebraTypeTemplate>,
    concrete: Rc<Node>,
    receiver: Rc<Node>,
    subst: Rc<HashMap<String, Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<HashMap<String, Rc<Node>>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || match (*template).clone() {
        AlgebraTypeTemplate::AlgebraTypeVariable { id: var_id, .. } => {
            if (v1_rt::map_get(&subst, var_id.clone()) != None) {
                subst.clone()
            } else {
                v1_rt::rc_map_insert(subst.clone(), var_id.clone(), concrete.clone())
            }
        }
        AlgebraTypeTemplate::ReceiverSelf => {
            let s1 = match concrete.children.clone().first().cloned() {
                Some(k) => {
                    if (v1_rt::map_get(&subst, "__key__".to_string()) != None) {
                        subst.clone()
                    } else {
                        v1_rt::rc_map_insert(
                            subst.clone(),
                            "__key__".to_string(),
                            child_type_node(k.clone()),
                        )
                    }
                }
                None => subst.clone(),
            };
            match concrete.children.clone().get(1 as usize).cloned() {
                Some(v) => {
                    if (v1_rt::map_get(&s1, "__value__".to_string()) != None) {
                        s1.clone()
                    } else {
                        v1_rt::rc_map_insert(
                            s1.clone(),
                            "__value__".to_string(),
                            child_type_node(v.clone()),
                        )
                    }
                }
                None => s1.clone(),
            }
        }
        AlgebraTypeTemplate::ReceiverKey => {
            if (v1_rt::map_get(&subst, "__key__".to_string()) != None) {
                subst.clone()
            } else {
                v1_rt::rc_map_insert(subst.clone(), "__key__".to_string(), concrete.clone())
            }
        }
        AlgebraTypeTemplate::ReceiverValue => {
            if (v1_rt::map_get(&subst, "__value__".to_string()) != None) {
                subst.clone()
            } else {
                v1_rt::rc_map_insert(subst.clone(), "__value__".to_string(), concrete.clone())
            }
        }
        AlgebraTypeTemplate::ReceiverElement => {
            if (v1_rt::map_get(&subst, "__element__".to_string()) != None) {
                subst.clone()
            } else {
                v1_rt::rc_map_insert(subst.clone(), "__element__".to_string(), concrete.clone())
            }
        }
        AlgebraTypeTemplate::CallableOf {
            return_type: ret_template,
            ..
        } => unify_template(
            ret_template.clone(),
            concrete.clone(),
            receiver.clone(),
            subst.clone(),
            source_indices.clone(),
        ),
        AlgebraTypeTemplate::ContainerOf {
            source: src,
            element: elem_template,
            ..
        } => {
            let expected_name = match (*src.clone()).clone() {
                ContainerSource::SameAsReceiver => {
                    authored_name_at(source_indices.clone(), receiver.clone())
                }
                ContainerSource::Named { name: n, .. } => n.clone(),
            };
            if (authored_name_at(source_indices.clone(), concrete.clone()) != expected_name) {
                subst.clone()
            } else {
                match concrete.children.clone().first().cloned() {
                    Some(child) => unify_template(
                        elem_template.clone(),
                        child_type_node(child.clone()),
                        receiver.clone(),
                        subst.clone(),
                        source_indices.clone(),
                    ),
                    None => subst.clone(),
                }
            }
        }
        AlgebraTypeTemplate::OptionalOf {
            inner: inner_template,
            ..
        } => match concrete.children.clone().first().cloned() {
            Some(child) => unify_template(
                inner_template.clone(),
                child_type_node(child.clone()),
                receiver.clone(),
                subst.clone(),
                source_indices.clone(),
            ),
            None => subst.clone(),
        },
        AlgebraTypeTemplate::TupleOf {
            first: ft,
            second: st,
            ..
        } => {
            let s2 = match concrete.children.clone().first().cloned() {
                Some(c) => unify_template(
                    ft.clone(),
                    child_type_node(c.clone()),
                    receiver.clone(),
                    subst.clone(),
                    source_indices.clone(),
                ),
                None => subst.clone(),
            };
            match concrete.children.clone().get(1 as usize).cloned() {
                Some(c) => unify_template(
                    st.clone(),
                    child_type_node(c.clone()),
                    receiver.clone(),
                    s2,
                    source_indices.clone(),
                ),
                None => s2,
            }
        }
        _ => subst.clone(),
    })
}

pub fn is_receiver_self(t: Rc<AlgebraTypeTemplate>) -> bool {
    match (*t).clone() {
        AlgebraTypeTemplate::ReceiverSelf => true,
        _ => false,
    }
}

pub fn build_type_substitution(
    param_templates: Rc<Vec<Rc<AlgebraTypeTemplate>>>,
    arg_types: Rc<Vec<Rc<Node>>>,
    receiver: Rc<Node>,
    base_subst: Rc<HashMap<String, Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<HashMap<String, Rc<Node>>> {
    {
        let first_is_self = match param_templates.clone().first().cloned() {
            Some(t) => is_receiver_self(t.clone()),
            None => false,
        };
        let non_receiver_templates = if first_is_self {
            Rc::new(
                param_templates
                    .clone()
                    .iter()
                    .cloned()
                    .skip(1 as usize)
                    .collect::<Vec<_>>(),
            )
        } else {
            param_templates.clone()
        };
        let pairs = Rc::new({
            let mut __result = Vec::new();
            for pair in Rc::new(
                non_receiver_templates
                    .iter()
                    .cloned()
                    .enumerate()
                    .map(|(i, v)| (i as i64, v))
                    .collect::<Vec<_>>(),
            )
            .iter()
            .cloned()
            {
                if (pair.0.clone() < (arg_types.clone().len() as i64)) {
                    __result.push(pair);
                }
            }
            __result
        });
        pairs.iter().cloned().fold(
            base_subst.clone(),
            |subst: Rc<HashMap<String, Rc<Node>>>, pair: (i64, Rc<AlgebraTypeTemplate>)| {
                let arg_type = match Rc::new({
                    let mut __result = Vec::new();
                    for ap in Rc::new({
                        let mut __result = Vec::new();
                        for ap in Rc::new(
                            arg_types
                                .clone()
                                .iter()
                                .cloned()
                                .enumerate()
                                .map(|(i, v)| (i as i64, v))
                                .collect::<Vec<_>>(),
                        )
                        .iter()
                        .cloned()
                        {
                            if (ap.0.clone() == pair.0.clone()) {
                                __result.push(ap);
                            }
                        }
                        __result
                    })
                    .iter()
                    .cloned()
                    {
                        __result.push(ap.1.clone());
                    }
                    __result
                })
                .first()
                .cloned()
                {
                    Some(a) => a.clone(),
                    None => error_type(),
                };
                unify_template(
                    pair.1.clone(),
                    arg_type.clone(),
                    receiver.clone(),
                    subst,
                    source_indices.clone(),
                )
            },
        )
    }
}

pub fn apply_type_substitution(
    template: Rc<AlgebraTypeTemplate>,
    subst: Rc<HashMap<String, Rc<Node>>>,
    receiver: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<KernelTypeBuild> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || match (*template).clone() {
        AlgebraTypeTemplate::AlgebraTypeVariable { id: var_id, .. } => {
            match v1_rt::map_get(&subst, var_id.clone()) {
                Some(resolved) => Rc::new(KernelTypeBuild {
                    ty: resolved.clone(),
                    diagnostics: Rc::new(vec![]),
                }),
                None => Rc::new(KernelTypeBuild {
                    ty: type_variable_node(var_id.clone()),
                    diagnostics: Rc::new(vec![]),
                }),
            }
        }
        AlgebraTypeTemplate::ReceiverSelf => {
            let receiver_name_str = authored_name_at(source_indices.clone(), receiver.clone());
            let is_bare = (is_container_type(receiver_name_str.clone()) && {
                let mut __all = true;
                for ch in receiver.children.clone().iter().cloned() {
                    if !({
                        let inner = child_type_node(ch.clone());
                        if (inner.inferred.clone() != None) {
                            is_type_variable(inner.inferred.clone().clone().unwrap())
                        } else {
                            ((inner.ident_span.clone() == None)
                                || !is_kernel_type(authored_name_at(
                                    source_indices.clone(),
                                    inner.clone(),
                                )))
                        }
                    }) {
                        __all = false;
                        break;
                    }
                }
                __all
            });
            if is_bare {
                {
                    let arity = container_expected_arity(receiver_name_str.clone());
                    if (arity.clone() == Some(2)) {
                        match v1_rt::map_get(&subst, "__key__".to_string()) {
                            Some(key) => {
                                let val = match v1_rt::map_get(&subst, "__value__".to_string()) {
                                    Some(v) => v.clone(),
                                    None => type_variable_node("V".to_string()),
                                };
                                make_map_type(key.clone(), val)
                            }
                            None => Rc::new(KernelTypeBuild {
                                ty: receiver.clone(),
                                diagnostics: Rc::new(vec![]),
                            }),
                        }
                    } else {
                        if (arity.clone() == Some(1)) {
                            match v1_rt::map_get(&subst, "__element__".to_string()) {
                                Some(elem) => {
                                    make_container_type(receiver_name_str.clone(), elem.clone())
                                }
                                None => Rc::new(KernelTypeBuild {
                                    ty: receiver.clone(),
                                    diagnostics: Rc::new(vec![]),
                                }),
                            }
                        } else {
                            Rc::new(KernelTypeBuild {
                                ty: receiver.clone(),
                                diagnostics: Rc::new(vec![]),
                            })
                        }
                    }
                }
            } else {
                Rc::new(KernelTypeBuild {
                    ty: receiver.clone(),
                    diagnostics: Rc::new(vec![]),
                })
            }
        }
        AlgebraTypeTemplate::ReceiverElement => match receiver.children.clone().first().cloned() {
            Some(child) => Rc::new(KernelTypeBuild {
                ty: child_type_node(child.clone()),
                diagnostics: Rc::new(vec![]),
            }),
            None => match v1_rt::map_get(&subst, "__element__".to_string()) {
                Some(elem) => Rc::new(KernelTypeBuild {
                    ty: elem.clone(),
                    diagnostics: Rc::new(vec![]),
                }),
                None => {
                    let rname = authored_name_at(source_indices.clone(), receiver.clone());
                    match container_param_name(rname.clone(), 0) {
                        Some(n) => Rc::new(KernelTypeBuild {
                            ty: type_variable_node(n.clone()),
                            diagnostics: Rc::new(vec![]),
                        }),
                        None => Rc::new(KernelTypeBuild {
                            ty: missing_kernel_container_profile_type(rname.clone()),
                            diagnostics: Rc::new(vec![kernel_container_profile_miss_diagnostic(
                                rname.clone(),
                            )]),
                        }),
                    }
                }
            },
        },
        AlgebraTypeTemplate::ReceiverKey => match receiver.children.clone().first().cloned() {
            Some(child) => Rc::new(KernelTypeBuild {
                ty: child_type_node(child.clone()),
                diagnostics: Rc::new(vec![]),
            }),
            None => match v1_rt::map_get(&subst, "__key__".to_string()) {
                Some(key) => Rc::new(KernelTypeBuild {
                    ty: key.clone(),
                    diagnostics: Rc::new(vec![]),
                }),
                None => {
                    let rname = authored_name_at(source_indices.clone(), receiver.clone());
                    match container_param_name(rname.clone(), 0) {
                        Some(n) => Rc::new(KernelTypeBuild {
                            ty: type_variable_node(n.clone()),
                            diagnostics: Rc::new(vec![]),
                        }),
                        None => Rc::new(KernelTypeBuild {
                            ty: missing_kernel_container_profile_type(rname.clone()),
                            diagnostics: Rc::new(vec![kernel_container_profile_miss_diagnostic(
                                rname.clone(),
                            )]),
                        }),
                    }
                }
            },
        },
        AlgebraTypeTemplate::ReceiverValue => {
            match receiver.children.clone().get(1 as usize).cloned() {
                Some(child) => Rc::new(KernelTypeBuild {
                    ty: child_type_node(child.clone()),
                    diagnostics: Rc::new(vec![]),
                }),
                None => match v1_rt::map_get(&subst, "__value__".to_string()) {
                    Some(val) => Rc::new(KernelTypeBuild {
                        ty: val,
                        diagnostics: Rc::new(vec![]),
                    }),
                    None => {
                        let rname = authored_name_at(source_indices.clone(), receiver.clone());
                        match container_param_name(rname.clone(), 1) {
                            Some(n) => Rc::new(KernelTypeBuild {
                                ty: type_variable_node(n.clone()),
                                diagnostics: Rc::new(vec![]),
                            }),
                            None => Rc::new(KernelTypeBuild {
                                ty: missing_kernel_container_profile_type(rname.clone()),
                                diagnostics: Rc::new(vec![
                                    kernel_container_profile_miss_diagnostic(rname.clone()),
                                ]),
                            }),
                        }
                    }
                },
            }
        }
        AlgebraTypeTemplate::NamedTemplate { name: n, .. } => Rc::new(KernelTypeBuild {
            ty: nominal_type_ref(n.clone()),
            diagnostics: Rc::new(vec![]),
        }),
        AlgebraTypeTemplate::ContainerOf {
            source: src,
            element: inner,
            ..
        } => {
            let kind_name = match (*src.clone()).clone() {
                ContainerSource::SameAsReceiver => {
                    authored_name_at(source_indices.clone(), receiver.clone())
                }
                ContainerSource::Named { name: n, .. } => n.clone(),
            };
            let inner_applied = apply_type_substitution(
                inner.clone(),
                subst.clone(),
                receiver.clone(),
                source_indices.clone(),
            );
            let built = make_container_type(kind_name, inner_applied.ty.clone());
            Rc::new(KernelTypeBuild {
                ty: built.ty.clone(),
                diagnostics: v1_rt::concat(
                    inner_applied.diagnostics.clone(),
                    built.diagnostics.clone(),
                ),
            })
        }
        AlgebraTypeTemplate::OptionalOf { inner: inner, .. } => {
            let ib = apply_type_substitution(
                inner.clone(),
                subst.clone(),
                receiver.clone(),
                source_indices.clone(),
            );
            Rc::new(KernelTypeBuild {
                ty: with_optional_cardinality(ib.ty.clone()),
                diagnostics: ib.diagnostics.clone(),
            })
        }
        AlgebraTypeTemplate::WitnessOf { inner: inner, .. } => {
            let ib = apply_type_substitution(
                inner.clone(),
                subst.clone(),
                receiver.clone(),
                source_indices.clone(),
            );
            let built = make_container_type("Witness".to_string(), ib.ty.clone());
            Rc::new(KernelTypeBuild {
                ty: built.ty.clone(),
                diagnostics: v1_rt::concat(ib.diagnostics.clone(), built.diagnostics.clone()),
            })
        }
        AlgebraTypeTemplate::TupleOf {
            first: ft,
            second: st,
            ..
        } => {
            let fb = apply_type_substitution(
                ft.clone(),
                subst.clone(),
                receiver.clone(),
                source_indices.clone(),
            );
            let sb = apply_type_substitution(
                st.clone(),
                subst.clone(),
                receiver.clone(),
                source_indices.clone(),
            );
            Rc::new(KernelTypeBuild {
                ty: make_tuple_type(fb.ty.clone(), sb.ty.clone()),
                diagnostics: v1_rt::concat(fb.diagnostics.clone(), sb.diagnostics.clone()),
            })
        }
        AlgebraTypeTemplate::CallableOf {
            params: p,
            return_type: r,
            ..
        } => {
            let param_bs = Rc::new({
                let mut __result = Vec::new();
                for tp in p.clone().iter().cloned() {
                    __result.push(apply_type_substitution(
                        tp.clone(),
                        subst.clone(),
                        receiver.clone(),
                        source_indices.clone(),
                    ));
                }
                __result
            });
            let param_nodes = Rc::new({
                let mut __result = Vec::new();
                for b in param_bs.clone().iter().cloned() {
                    __result.push(b.ty.clone());
                }
                __result
            });
            let param_diags = Rc::new({
                let mut __result = Vec::new();
                for b in param_bs.clone().iter().cloned() {
                    __result.extend((*b.diagnostics.clone()).iter().cloned());
                }
                __result
            });
            let rb = apply_type_substitution(
                r.clone(),
                subst.clone(),
                receiver.clone(),
                source_indices.clone(),
            );
            Rc::new(KernelTypeBuild {
                ty: make_callable_type(
                    Rc::new({
                        let mut __result = Vec::new();
                        for pn in param_nodes.iter().cloned() {
                            __result.push(make_param_node(
                                "_".to_string(),
                                pn.clone(),
                                None,
                                no_span(),
                                no_span(),
                            ));
                        }
                        __result
                    }),
                    rb.ty.clone(),
                ),
                diagnostics: v1_rt::concat(param_diags, rb.diagnostics.clone()),
            })
        }
    })
}

pub fn template_return_is_receiver_self(template: Rc<AlgebraFieldTemplate>) -> bool {
    is_receiver_self(template.return_type.clone())
}

pub fn template_return_has_variables(template: Rc<AlgebraFieldTemplate>) -> bool {
    has_type_variable(template.return_type.clone())
}

pub fn has_type_variable(t: Rc<AlgebraTypeTemplate>) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || match (*t).clone() {
        AlgebraTypeTemplate::AlgebraTypeVariable { id: _, .. } => true,
        AlgebraTypeTemplate::ContainerOf { element: inner, .. } => has_type_variable(inner.clone()),
        AlgebraTypeTemplate::OptionalOf { inner: inner, .. } => has_type_variable(inner.clone()),
        AlgebraTypeTemplate::WitnessOf { inner: inner, .. } => has_type_variable(inner.clone()),
        AlgebraTypeTemplate::TupleOf {
            first: f,
            second: s,
            ..
        } => (has_type_variable(f.clone()) || has_type_variable(s.clone())),
        AlgebraTypeTemplate::CallableOf { return_type: r, .. } => has_type_variable(r.clone()),
        _ => false,
    })
}

pub fn resolve_type_variables_from_template(
    template: Rc<AlgebraFieldTemplate>,
    arg_types: Rc<Vec<Rc<Node>>>,
    receiver_type: Rc<Node>,
    overrides: Rc<HashMap<String, Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<KernelTypeBuild> {
    {
        let subst = build_type_substitution(
            template.param_types.clone(),
            arg_types,
            receiver_type.clone(),
            overrides,
            source_indices.clone(),
        );
        apply_type_substitution(
            template.return_type.clone(),
            subst,
            receiver_type.clone(),
            source_indices.clone(),
        )
    }
}

pub fn callable_inferred(n: Rc<Node>) -> Rc<Node> {
    {
        let is_callable = ((n.params.clone().len() as i64) > 0);
        if is_callable {
            match n.inferred.clone().as_deref().cloned() {
                Some(InferredNode::Resolved { node: ret, .. }) => ret.clone(),
                None => error_type(),
                _ => error_type(),
            }
        } else {
            n.clone()
        }
    }
}

pub fn normalize_access_type_node(mut n: Rc<Node>) -> Rc<Node> {
    loop {
        let has_structure = (n.connective.clone() != Connective::NoConnective);
        let unwrapped = if ((n.type_annotation.clone() != None) && has_structure) {
            n.children.clone().first().cloned()
        } else {
            None
        };
        match unwrapped {
            Some(base) => {
                let __tco_0 = base.clone();
                n = __tco_0;
                continue;
            }
            None => {
                break n.clone();
            }
        }
    }
}

pub fn node_type_shape(
    n: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let __is_leaf = (((n.connective.clone() == Connective::NoConnective)
            && ((n.children.clone().len() as i64) == 0))
            && ((n.properties.clone().len() as i64) == 0));
        let n_name = authored_name_at(source_indices.clone(), n.clone());
        if __is_leaf {
            {
                let __is_named_ref = match n.inferred.clone().as_deref().cloned() {
                    Some(InferredNode::Resolved { node: rt, .. }) => {
                        (((((rt.connective.clone() == Connective::NoConnective)
                            && ((rt.children.clone().len() as i64) == 0))
                            && (rt.ident_span.clone() != None))
                            && (authored_name_at(source_indices.clone(), rt.clone())
                                != "None".to_string()))
                            && (is_kernel_type(authored_name_at(
                                source_indices.clone(),
                                rt.clone(),
                            )) == false))
                    }
                    _ => false,
                };
                if __is_named_ref {
                    v1_rt::concat(v1_rt::concat("Named(".to_string(), n_name), ")".to_string())
                } else {
                    v1_rt::concat(
                        v1_rt::concat("Primitive(".to_string(), n_name),
                        ")".to_string(),
                    )
                }
            }
        } else {
            {
                let is_product = (n.connective.clone() == Connective::Conj);
                let is_coproduct = (n.connective.clone() == Connective::Disj);
                if is_product {
                    if (n.ident_span.clone() == None) {
                        "Product(<anon>)".to_string()
                    } else {
                        v1_rt::concat(
                            v1_rt::concat("Product(".to_string(), n_name),
                            ")".to_string(),
                        )
                    }
                } else {
                    if is_coproduct {
                        if (n.ident_span.clone() == None) {
                            "Coproduct(<anon>)".to_string()
                        } else {
                            v1_rt::concat(
                                v1_rt::concat("Coproduct(".to_string(), n_name),
                                ")".to_string(),
                            )
                        }
                    } else {
                        {
                            let __is_container =
                                node_is_element_collection(n.clone(), source_indices.clone());
                            let is_optional =
                                (n.return_cardinality.clone() == Cardinality::CardOptional);
                            let is_map =
                                node_is_keyed_collection(n.clone(), source_indices.clone());
                            if __is_container {
                                {
                                    let elem_shape = match n.children.clone().first().cloned() {
                                        Some(el) => node_type_shape(
                                            child_type_node(el.clone()),
                                            source_indices.clone(),
                                        ),
                                        None => "?".to_string(),
                                    };
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat("Container(".to_string(), n_name),
                                                ",".to_string(),
                                            ),
                                            elem_shape,
                                        ),
                                        ")".to_string(),
                                    )
                                }
                            } else {
                                if is_optional {
                                    {
                                        let inner_shape = node_type_shape(
                                            with_required_cardinality(n.clone()),
                                            source_indices.clone(),
                                        );
                                        v1_rt::concat(
                                            v1_rt::concat("Optional(".to_string(), inner_shape),
                                            ")".to_string(),
                                        )
                                    }
                                } else {
                                    if is_map {
                                        "Map(...)".to_string()
                                    } else {
                                        v1_rt::concat(
                                            v1_rt::concat("Node(".to_string(), n_name),
                                            ")".to_string(),
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    })
}

pub fn node_type_compatible(
    mut left: Rc<Node>,
    mut right: Rc<Node>,
    mut source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    loop {
        let left_err = if (left.inferred.clone() != None) {
            is_compiler_error(left.inferred.clone().clone().unwrap())
        } else {
            false
        };
        let right_err = if (right.inferred.clone() != None) {
            is_compiler_error(right.inferred.clone().clone().unwrap())
        } else {
            false
        };
        let left_tv = if (left.inferred.clone() != None) {
            is_type_variable(left.inferred.clone().clone().unwrap())
        } else {
            false
        };
        let right_tv = if (right.inferred.clone() != None) {
            is_type_variable(right.inferred.clone().clone().unwrap())
        } else {
            false
        };
        let left_opt = (left.return_cardinality.clone() == Cardinality::CardOptional);
        let right_opt = (right.return_cardinality.clone() == Cardinality::CardOptional);
        let right_is_unit = is_unit_like(right.clone());
        let left_is_unit = is_unit_like(left.clone());
        if (left_err || right_err) {
            break true;
        } else {
            if (left_tv || right_tv) {
                break true;
            } else {
                if (left_opt.clone() && right_is_unit) {
                    break true;
                } else {
                    if (left_is_unit && right_opt.clone()) {
                        break true;
                    } else {
                        let left_is_container =
                            node_is_element_collection(left.clone(), source_indices.clone());
                        let right_is_container =
                            node_is_element_collection(right.clone(), source_indices.clone());
                        if (left_is_container && right_is_container) {
                            if (canonical_template_name(left.clone(), source_indices.clone())
                                != canonical_template_name(right.clone(), source_indices.clone()))
                            {
                                break false;
                            } else {
                                match left.children.clone().first().cloned() {
                                    Some(left_ch) => {
                                        match right.children.clone().first().cloned() {
                                            Some(right_ch) => {
                                                let left_el = child_type_node(left_ch.clone());
                                                let right_el = child_type_node(right_ch.clone());
                                                let left_el_is_unit = is_unit_like(left_el.clone());
                                                let right_el_is_unit =
                                                    is_unit_like(right_el.clone());
                                                if (left_el_is_unit || right_el_is_unit) {
                                                    break true;
                                                } else {
                                                    {
                                                        let __tco_0 = left_el.clone();
                                                        let __tco_1 = right_el.clone();
                                                        left = __tco_0;
                                                        right = __tco_1;
                                                        continue;
                                                    }
                                                }
                                            }
                                            None => {
                                                break true;
                                            }
                                        }
                                    }
                                    None => {
                                        break true;
                                    }
                                }
                            }
                        } else {
                            if (((((canonical_template_name(
                                left.clone(),
                                source_indices.clone(),
                            ) == canonical_template_name(
                                right.clone(),
                                source_indices.clone(),
                            )) && (authored_name_at(
                                source_indices.clone(),
                                left.clone(),
                            ) != authored_name_at(
                                source_indices.clone(),
                                right.clone(),
                            ))) && ((left.children.clone().len() as i64) == 1))
                                && ((right.children.clone().len() as i64) == 1))
                                && (is_declared_container_alias_spelling(authored_name_at(
                                    source_indices.clone(),
                                    left.clone(),
                                )) || is_declared_container_alias_spelling(authored_name_at(
                                    source_indices.clone(),
                                    right.clone(),
                                ))))
                            {
                                match left.children.clone().first().cloned() {
                                    Some(left_ch) => {
                                        match right.children.clone().first().cloned() {
                                            Some(right_ch) => {
                                                let left_el = child_type_node(left_ch.clone());
                                                let right_el = child_type_node(right_ch.clone());
                                                if (is_unit_like(left_el.clone())
                                                    || is_unit_like(right_el.clone()))
                                                {
                                                    break true;
                                                } else {
                                                    {
                                                        let __tco_0 = left_el.clone();
                                                        let __tco_1 = right_el.clone();
                                                        left = __tco_0;
                                                        right = __tco_1;
                                                        continue;
                                                    }
                                                }
                                            }
                                            None => {
                                                break true;
                                            }
                                        }
                                    }
                                    None => {
                                        break true;
                                    }
                                }
                            } else {
                                if (left_opt.clone() && right_opt.clone()) {
                                    let left_inner = with_required_cardinality(left.clone());
                                    let right_inner = with_required_cardinality(right.clone());
                                    let left_inner_is_unit = is_unit_like(left_inner.clone());
                                    let right_inner_is_unit = is_unit_like(right_inner.clone());
                                    if (left_inner_is_unit || right_inner_is_unit) {
                                        break true;
                                    } else {
                                        {
                                            let __tco_0 = left_inner.clone();
                                            let __tco_1 = right_inner.clone();
                                            left = __tco_0;
                                            right = __tco_1;
                                            continue;
                                        }
                                    }
                                } else {
                                    if (left_opt.clone() || right_opt.clone()) {
                                        break false;
                                    } else {
                                        break (authored_name_at(
                                            source_indices.clone(),
                                            left.clone(),
                                        ) == authored_name_at(
                                            source_indices.clone(),
                                            right.clone(),
                                        ));
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn prefer_specific_type(
    left: Rc<Node>,
    right: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Node> {
    {
        let left_is_container = node_is_element_collection(left.clone(), source_indices.clone());
        let left_is_optional = (left.return_cardinality.clone() == Cardinality::CardOptional);
        let left_first_child = left.children.clone().first().cloned();
        let left_norm_name = authored_name_at(source_indices.clone(), left.clone());
        let left_is_unit_inner = if left_is_container.clone() {
            match left_first_child {
                Some(ch) => {
                    let el = child_type_node(ch.clone());
                    let el_is_unit = is_unit_like(el);
                    el_is_unit
                }
                None => false,
            }
        } else {
            if left_is_optional.clone() {
                {
                    let left_is_unit = is_unit_like(left.clone());
                    left_is_unit
                }
            } else {
                false
            }
        };
        let right_is_container = node_is_element_collection(right.clone(), source_indices.clone());
        let right_is_optional = (right.return_cardinality.clone() == Cardinality::CardOptional);
        let same_kind = if (left_is_container.clone() && right_is_container) {
            (left_norm_name == authored_name_at(source_indices.clone(), right.clone()))
        } else {
            if (left_is_optional.clone() && right_is_optional) {
                true
            } else {
                false
            }
        };
        if (same_kind && left_is_unit_inner) {
            right.clone()
        } else {
            if (is_fully_resolved(right.clone(), source_indices.clone())
                && !is_fully_resolved(left.clone(), source_indices.clone()))
            {
                right.clone()
            } else {
                left.clone()
            }
        }
    }
}

pub fn node_type_equals(
    left: Rc<Node>,
    right: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let left_err = if (left.inferred.clone() != None) {
            is_compiler_error(left.inferred.clone().clone().unwrap())
        } else {
            false
        };
        let right_err = if (right.inferred.clone() != None) {
            is_compiler_error(right.inferred.clone().clone().unwrap())
        } else {
            false
        };
        let left_tv = if (left.inferred.clone() != None) {
            is_type_variable(left.inferred.clone().clone().unwrap())
        } else {
            false
        };
        let right_tv = if (right.inferred.clone() != None) {
            is_type_variable(right.inferred.clone().clone().unwrap())
        } else {
            false
        };
        let left_opt = (left.return_cardinality.clone() == Cardinality::CardOptional);
        let right_opt = (right.return_cardinality.clone() == Cardinality::CardOptional);
        let right_is_unit_eq = is_unit_like(right.clone());
        let left_is_unit_eq = is_unit_like(left.clone());
        if (left_err || right_err) {
            true
        } else {
            if (left_tv.clone() && right_tv.clone()) {
                true
            } else {
                if (left_tv.clone() || right_tv.clone()) {
                    false
                } else {
                    if (left_opt.clone() && right_is_unit_eq) {
                        true
                    } else {
                        if (left_is_unit_eq && right_opt.clone()) {
                            true
                        } else {
                            if (left_opt.clone() && right_opt.clone()) {
                                node_type_equals_core(
                                    with_required_cardinality(left.clone()),
                                    with_required_cardinality(right.clone()),
                                    source_indices,
                                )
                            } else {
                                node_type_equals_core(left.clone(), right.clone(), source_indices)
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn node_type_equals_core(
    left: Rc<Node>,
    right: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let left_leaf = (((left.connective.clone() == Connective::NoConnective)
            && ((left.children.clone().len() as i64) == 0))
            && ((left.properties.clone().len() as i64) == 0));
        let right_leaf = (((right.connective.clone() == Connective::NoConnective)
            && ((right.children.clone().len() as i64) == 0))
            && ((right.properties.clone().len() as i64) == 0));
        let left_struct = (left.connective.clone() != Connective::NoConnective);
        let right_struct = (right.connective.clone() != Connective::NoConnective);
        let left_name = authored_name_at(source_indices.clone(), left.clone());
        let right_name = authored_name_at(source_indices.clone(), right.clone());
        if (left_leaf.clone() && right_leaf.clone()) {
            (left_name == right_name)
        } else {
            if (left_struct.clone() && right_struct.clone()) {
                if (left_name != right_name) {
                    false
                } else {
                    if ((left.connective.clone() == Connective::Conj)
                        != (right.connective.clone() == Connective::Conj))
                    {
                        false
                    } else {
                        if ((left.children.clone().len() as i64)
                            != (right.children.clone().len() as i64))
                        {
                            false
                        } else {
                            {
                                let mut __all = true;
                                for pair in Rc::new(
                                    left.children
                                        .clone()
                                        .iter()
                                        .cloned()
                                        .enumerate()
                                        .map(|(i, v)| (i as i64, v))
                                        .collect::<Vec<_>>(),
                                )
                                .iter()
                                .cloned()
                                {
                                    if !(match right
                                        .children
                                        .clone()
                                        .get(pair.0.clone() as usize)
                                        .cloned()
                                    {
                                        Some(right_child) => node_type_equals(
                                            pair.1.clone(),
                                            right_child.clone(),
                                            source_indices.clone(),
                                        ),
                                        None => false,
                                    }) {
                                        __all = false;
                                        break;
                                    }
                                }
                                __all
                            }
                        }
                    }
                }
            } else {
                if (left_leaf.clone() && right_struct.clone()) {
                    (left_name == right_name)
                } else {
                    if (left_struct.clone() && right_leaf.clone()) {
                        (left_name == right_name)
                    } else {
                        {
                            let left_is_container =
                                node_is_element_collection(left.clone(), source_indices.clone());
                            let right_is_container =
                                node_is_element_collection(right.clone(), source_indices.clone());
                            if (left_is_container && right_is_container) {
                                if (left_name != right_name) {
                                    false
                                } else {
                                    match left.children.clone().first().cloned() {
                                        Some(left_ch) => {
                                            match right.children.clone().first().cloned() {
                                                Some(right_ch) => node_type_equals(
                                                    child_type_node(left_ch.clone()),
                                                    child_type_node(right_ch.clone()),
                                                    source_indices.clone(),
                                                ),
                                                None => false,
                                            }
                                        }
                                        None => false,
                                    }
                                }
                            } else {
                                {
                                    let both_maps = (node_is_keyed_collection(
                                        left.clone(),
                                        source_indices.clone(),
                                    ) && node_is_keyed_collection(
                                        right.clone(),
                                        source_indices.clone(),
                                    ));
                                    if both_maps {
                                        if (((left.children.clone().len() as i64) == 2)
                                            && ((right.children.clone().len() as i64) == 2))
                                        {
                                            match left.children.clone().first().cloned() {
                                                Some(left_first) => {
                                                    match right.children.clone().first().cloned() {
                                                        Some(right_first) => match left
                                                            .children
                                                            .clone()
                                                            .get(1 as usize)
                                                            .cloned()
                                                        {
                                                            Some(left_second) => match right
                                                                .children
                                                                .clone()
                                                                .get(1 as usize)
                                                                .cloned()
                                                            {
                                                                Some(right_second) => {
                                                                    (node_type_equals(
                                                                        child_type_node(
                                                                            left_first.clone(),
                                                                        ),
                                                                        child_type_node(
                                                                            right_first.clone(),
                                                                        ),
                                                                        source_indices.clone(),
                                                                    ) && node_type_equals(
                                                                        child_type_node(
                                                                            left_second.clone(),
                                                                        ),
                                                                        child_type_node(
                                                                            right_second.clone(),
                                                                        ),
                                                                        source_indices.clone(),
                                                                    ))
                                                                }
                                                                None => false,
                                                            },
                                                            None => false,
                                                        },
                                                        None => false,
                                                    }
                                                }
                                                None => false,
                                            }
                                        } else {
                                            false
                                        }
                                    } else {
                                        if (((left.params.clone().len() as i64) > 0)
                                            && ((right.params.clone().len() as i64) > 0))
                                        {
                                            if ((left.params.clone().len() as i64)
                                                != (right.params.clone().len() as i64))
                                            {
                                                false
                                            } else {
                                                {
                                                    let params_eq = {
                                                        let mut __all = true;
                                                        for pair in Rc::new(
                                                            left.params
                                                                .clone()
                                                                .iter()
                                                                .cloned()
                                                                .enumerate()
                                                                .map(|(i, v)| (i as i64, v))
                                                                .collect::<Vec<_>>(),
                                                        )
                                                        .iter()
                                                        .cloned()
                                                        {
                                                            if !(match right
                                                                .params
                                                                .clone()
                                                                .get(pair.0.clone() as usize)
                                                                .cloned()
                                                            {
                                                                Some(right_param) => {
                                                                    node_type_equals(
                                                                        param_node_type_expr(
                                                                            pair.1.clone(),
                                                                        ),
                                                                        param_node_type_expr(
                                                                            right_param.clone(),
                                                                        ),
                                                                        source_indices.clone(),
                                                                    )
                                                                }
                                                                None => false,
                                                            }) {
                                                                __all = false;
                                                                break;
                                                            }
                                                        }
                                                        __all
                                                    };
                                                    if (params_eq == false) {
                                                        false
                                                    } else {
                                                        match left
                                                            .inferred
                                                            .clone()
                                                            .as_deref()
                                                            .cloned()
                                                        {
                                                            Some(InferredNode::Resolved {
                                                                node: left_ret,
                                                                ..
                                                            }) => match right
                                                                .inferred
                                                                .clone()
                                                                .as_deref()
                                                                .cloned()
                                                            {
                                                                Some(InferredNode::Resolved {
                                                                    node: right_ret,
                                                                    ..
                                                                }) => node_type_equals(
                                                                    left_ret.clone(),
                                                                    right_ret.clone(),
                                                                    source_indices.clone(),
                                                                ),
                                                                None => false,
                                                                _ => false,
                                                            },
                                                            None => {
                                                                (right.inferred.clone() == None)
                                                            }
                                                            _ => false,
                                                        }
                                                    }
                                                }
                                            }
                                        } else {
                                            false
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn node_type_deps(
    n: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<String>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let n_is_type_var = if (n.inferred.clone() != None) {
            is_type_variable(n.inferred.clone().clone().unwrap())
        } else {
            false
        };
        if n_is_type_var {
            return Rc::new(vec![]);
        }
        let __is_named_ref = if (n.inferred.clone() == None) {
            false
        } else {
            match n.inferred.clone().as_deref().cloned() {
                Some(InferredNode::Resolved { node: rt, .. }) => {
                    (((((rt.connective.clone() == Connective::NoConnective)
                        && ((rt.children.clone().len() as i64) == 0))
                        && (rt.ident_span.clone() != None))
                        && (authored_name_at(source_indices.clone(), rt.clone())
                            != "None".to_string()))
                        && (is_kernel_type(authored_name_at(source_indices.clone(), rt.clone()))
                            == false))
                }
                _ => false,
            }
        };
        let has_structure = (n.connective.clone() != Connective::NoConnective);
        let n_name = authored_name_at(source_indices.clone(), n.clone());
        if __is_named_ref {
            match n.inferred.clone().as_deref().cloned() {
                Some(InferredNode::Resolved { node: rt, .. }) => {
                    Rc::new(vec![authored_name_at(source_indices.clone(), rt.clone())])
                }
                _ => Rc::new(vec![]),
            }
        } else {
            if has_structure {
                Rc::new({
                    let mut __result = Vec::new();
                    for child in n.children.clone().iter().cloned() {
                        __result.extend(
                            (*match child.inferred.clone().as_deref().cloned() {
                                Some(InferredNode::Resolved { node: rt, .. }) => {
                                    node_type_deps(rt.clone(), source_indices.clone())
                                }
                                _ => {
                                    if (child.inferred.clone() == None) {
                                        node_type_deps(child.clone(), source_indices.clone())
                                    } else {
                                        Rc::new(vec![])
                                    }
                                }
                            })
                            .iter()
                            .cloned(),
                        );
                    }
                    __result
                })
            } else {
                if (n.inferred.clone() != None) {
                    match n.inferred.clone().as_deref().cloned() {
                        Some(InferredNode::Resolved { node: rt, .. }) => {
                            node_type_deps(rt.clone(), source_indices.clone())
                        }
                        _ => Rc::new(vec![]),
                    }
                } else {
                    if ((n.children.clone().len() as i64) > 0) {
                        {
                            let child_deps = Rc::new({
                                let mut __result = Vec::new();
                                for child in n.children.clone().iter().cloned() {
                                    __result.extend(
                                        (*node_type_deps(child.clone(), source_indices.clone()))
                                            .iter()
                                            .cloned(),
                                    );
                                }
                                __result
                            });
                            if ((n.ident_span.clone() != None)
                                && (is_kernel_type(n_name.clone()) == false))
                            {
                                v1_rt::concat(Rc::new(vec![n_name.clone()]), child_deps)
                            } else {
                                child_deps
                            }
                        }
                    } else {
                        if ((is_kernel_type(n_name.clone())
                            || (n_name.clone() == "None".to_string()))
                            || (n.ident_span.clone() == None))
                        {
                            Rc::new(vec![])
                        } else {
                            Rc::new(vec![n_name.clone()])
                        }
                    }
                }
            }
        }
    })
}

pub fn infer_literal_node(lit: Rc<LiteralValue>) -> Rc<Node> {
    match (*lit).clone() {
        LiteralValue::LitStr { value: _, .. } => string_type(),
        LiteralValue::LitInt { value: _, .. } => int_type(),
        LiteralValue::LitFloat { value: _, .. } => float_type(),
        LiteralValue::LitBool { value: _, .. } => bool_type(),
        LiteralValue::LitNull => with_optional_cardinality(unit_type()),
        LiteralValue::LitSymbol { value: _, .. } => string_type(),
    }
}

pub fn method_receiver_element_node(
    receiver_type: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Node> {
    {
        let normed = normalize_access_type_node(receiver_type.clone());
        let maybe_element = if node_is_keyed_collection(normed.clone(), source_indices) {
            match normed.children.clone().get(1 as usize).cloned() {
                Some(ch) => Some(child_type_node(ch.clone())),
                None => None,
            }
        } else {
            if ((normed.connective.clone() == Connective::NoConnective)
                && ((normed.children.clone().len() as i64) == 1))
            {
                match normed.children.clone().first().cloned() {
                    Some(ch) => Some(child_type_node(ch.clone())),
                    None => None,
                }
            } else {
                None
            }
        };
        match maybe_element {
            Some(el) => el.clone(),
            None => receiver_type.clone(),
        }
    }
}

pub fn extract_optional_inner_node(n: Rc<Node>) -> Rc<Node> {
    {
        let is_optional = (n.return_cardinality.clone() == Cardinality::CardOptional);
        if is_optional {
            with_required_cardinality(n.clone())
        } else {
            if ((n.name.clone() == "Optional".to_string())
                && ((n.children.clone().len() as i64) == 1))
            {
                match n.children.clone().first().cloned() {
                    Some(inner) => inner.clone(),
                    None => n.clone(),
                }
            } else {
                n.clone()
            }
        }
    }
}

pub fn algebra_field_kind_name(kind: AlgebraFieldKind) -> String {
    match kind {
        AlgebraFieldKind::AlgAdd => "add".to_string(),
        AlgebraFieldKind::AlgMul => "mul".to_string(),
        AlgebraFieldKind::AlgReciprocal => "reciprocal".to_string(),
        AlgebraFieldKind::AlgQuotient => "quotient".to_string(),
        AlgebraFieldKind::AlgRemainder => "remainder".to_string(),
        AlgebraFieldKind::AlgCompare => "compare".to_string(),
        AlgebraFieldKind::AlgMeet => "meet".to_string(),
        AlgebraFieldKind::AlgJoin => "join".to_string(),
    }
}

pub fn binop_algebra_fields(op: BinOp) -> Rc<Vec<AlgebraFieldKind>> {
    match op {
        BinOp::Add => Rc::new(vec![AlgebraFieldKind::AlgAdd]),
        BinOp::Sub => Rc::new(vec![AlgebraFieldKind::AlgAdd]),
        BinOp::Mul => Rc::new(vec![AlgebraFieldKind::AlgMul]),
        BinOp::Div => Rc::new(vec![
            AlgebraFieldKind::AlgReciprocal,
            AlgebraFieldKind::AlgQuotient,
        ]),
        BinOp::Mod => Rc::new(vec![AlgebraFieldKind::AlgRemainder]),
        BinOp::Eq => Rc::new(vec![AlgebraFieldKind::AlgCompare]),
        BinOp::Ne => Rc::new(vec![AlgebraFieldKind::AlgCompare]),
        BinOp::Lt => Rc::new(vec![AlgebraFieldKind::AlgCompare]),
        BinOp::Gt => Rc::new(vec![AlgebraFieldKind::AlgCompare]),
        BinOp::Le => Rc::new(vec![AlgebraFieldKind::AlgCompare]),
        BinOp::Ge => Rc::new(vec![AlgebraFieldKind::AlgCompare]),
        BinOp::And => Rc::new(vec![AlgebraFieldKind::AlgMeet]),
        BinOp::Or => Rc::new(vec![AlgebraFieldKind::AlgJoin]),
        BinOp::NullCoalesce => Rc::new(vec![]),
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct AlgebraFieldMatch {
    pub field_kind: AlgebraFieldKind,
    pub field_node: Rc<Node>,
}

pub fn first_matching_algebra_field(
    mut n: Rc<Node>,
    mut candidates: Rc<Vec<AlgebraFieldKind>>,
    mut source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<Rc<AlgebraFieldMatch>> {
    loop {
        match candidates.clone().first().cloned() {
            None => {
                break None;
            }
            Some(kind) => {
                match find_child_named(
                    n.clone(),
                    algebra_field_kind_name(kind.clone()),
                    source_indices.clone(),
                ) {
                    Some(f) => {
                        break Some(Rc::new(AlgebraFieldMatch {
                            field_kind: kind.clone(),
                            field_node: f.clone(),
                        }));
                    }
                    None => {
                        let __tco_0 = Rc::new(
                            candidates
                                .iter()
                                .cloned()
                                .skip(1 as usize)
                                .collect::<Vec<_>>(),
                        );
                        candidates = __tco_0;
                        continue;
                    }
                }
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct BinOpInferred {
    pub result_type: Rc<Node>,
    pub algebra_field: Option<AlgebraFieldKind>,
}

pub fn infer_binop_type_node(
    op: BinOp,
    left_type: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<BinOpInferred> {
    match op.clone() {
        BinOp::Eq => Rc::new(BinOpInferred {
            result_type: bool_type(),
            algebra_field: None,
        }),
        BinOp::Ne => Rc::new(BinOpInferred {
            result_type: bool_type(),
            algebra_field: None,
        }),
        BinOp::Lt => Rc::new(BinOpInferred {
            result_type: bool_type(),
            algebra_field: None,
        }),
        BinOp::Gt => Rc::new(BinOpInferred {
            result_type: bool_type(),
            algebra_field: None,
        }),
        BinOp::Le => Rc::new(BinOpInferred {
            result_type: bool_type(),
            algebra_field: None,
        }),
        BinOp::Ge => Rc::new(BinOpInferred {
            result_type: bool_type(),
            algebra_field: None,
        }),
        BinOp::And => Rc::new(BinOpInferred {
            result_type: bool_type(),
            algebra_field: None,
        }),
        BinOp::Or => Rc::new(BinOpInferred {
            result_type: bool_type(),
            algebra_field: None,
        }),
        BinOp::NullCoalesce => Rc::new(BinOpInferred {
            result_type: extract_optional_inner_node(left_type.clone()),
            algebra_field: None,
        }),
        _ => {
            let candidates = binop_algebra_fields(op.clone());
            let is_product = (left_type.connective.clone() == Connective::Conj);
            if is_product {
                match first_matching_algebra_field(left_type.clone(), candidates, source_indices) {
                    Some(m) => match m.field_node.clone().inferred.clone().as_deref().cloned() {
                        Some(InferredNode::Resolved { node: rt, .. }) => {
                            if ((rt.params.clone().len() as i64) > 0) {
                                match rt.inferred.clone().as_deref().cloned() {
                                    Some(InferredNode::Resolved {
                                        node: return_type, ..
                                    }) => Rc::new(BinOpInferred {
                                        result_type: return_type.clone(),
                                        algebra_field: Some(m.field_kind.clone()),
                                    }),
                                    _ => Rc::new(BinOpInferred {
                                        result_type: left_type.clone(),
                                        algebra_field: Some(m.field_kind.clone()),
                                    }),
                                }
                            } else {
                                Rc::new(BinOpInferred {
                                    result_type: rt.clone(),
                                    algebra_field: Some(m.field_kind.clone()),
                                })
                            }
                        }
                        _ => Rc::new(BinOpInferred {
                            result_type: left_type.clone(),
                            algebra_field: None,
                        }),
                    },
                    None => Rc::new(BinOpInferred {
                        result_type: left_type.clone(),
                        algebra_field: None,
                    }),
                }
            } else {
                Rc::new(BinOpInferred {
                    result_type: left_type.clone(),
                    algebra_field: None,
                })
            }
        }
    }
}

pub fn for_each_element_type_node(
    n: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Node> {
    {
        let normed = normalize_access_type_node(n);
        let is_single_child = ((normed.connective.clone() == Connective::NoConnective)
            && ((normed.children.clone().len() as i64) == 1));
        let extracted = if is_single_child {
            match normed.children.clone().first().cloned() {
                Some(ch) => Some(child_type_node(ch.clone())),
                None => None,
            }
        } else {
            None
        };
        match extracted {
            Some(el) => el.clone(),
            None => {
                if ((((normed.connective.clone() == Connective::NoConnective)
                    && ((normed.children.clone().len() as i64) == 0))
                    && ((normed.properties.clone().len() as i64) == 0))
                    && (authored_name_at(source_indices, normed.clone()) == "String".to_string()))
                {
                    string_type()
                } else {
                    normed.clone()
                }
            }
        }
    }
}

pub fn emit_map_has(m: Rc<HashMap<String, bool>>, key: String) -> bool {
    match v1_rt::map_get(&m, key) {
        Some(_) => true,
        None => false,
    }
}
